// Generated by tools/gen_quest_voices.py from src/narration-quests-text.json (ajan:quests). Do not edit by hand.
// Adds story/quest lines to BABA.Narration (tr-TR-AhmetNeural) and BABA.NarrationEN (en-US-SteffanNeural).
window.BABA = window.BABA || {};
(function (B) {
  B.Narration = B.Narration || {}; B.NarrationEN = B.NarrationEN || {};
  var TR = {"story1": {"text": "Yirmi yıl boyunca Kara Defter'e adlar yazdın, Bahtiyar. Bu zincirlerin her halkası senin mürekkebinle başladı.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.02, "chapter": 1, "audio": ""}, "truth1": {"text": "Cellat son nefesinde fısıldıyor: Sen yazdın, ben kestim. Seni gömen kürek, senin kalemindi.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.51, "chapter": 1, "audio": ""}, "rescue1": {"text": "Derviş yemin taşına ulaştı. Adını sen yazmıştın; o yine de sana matarasını bıraktı.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.46, "chapter": 1, "audio": ""}, "hunt1": {"text": "Kefen Dokuyucu düştü. Dokuduğu kefenlerin hiçbiri ölüler için değildi.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.29, "chapter": 1, "audio": ""}, "pages1": {"text": "Sayfalar senin el yazın. Son satırda bir ad var, mürekkebi henüz kurumamış: Selvi.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.03, "chapter": 1, "audio": ""}, "altar1": {"text": "Kan sunağı hâlâ sıcak. Bedel isteyen her şey gibi, o da seni bekliyordu.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.95, "chapter": 1, "audio": ""}, "story2": {"text": "Selvi bu kıyıdan geçti. Çancı onu tekneye bindirdi. Sen de Defter'e borç ödendi diye yazdın.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.13, "chapter": 2, "audio": ""}, "truth2": {"text": "Çan sustu. Çancının son sözü: Kardeşin boğulmadı, kâtip. Onu Krala sattım.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.59, "chapter": 2, "audio": ""}, "rescue2": {"text": "Kerem fenere ulaştı. Babası çanı ağlayarak çalmıştı. Kıyıda ilk kez biri, dönenler için dua ediyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 10.03, "chapter": 2, "audio": ""}, "hunt2": {"text": "Tuz İçindeki Yeminli düştü. Tuz çatlarken içinden bir anahtar ve bir tekne kaydı döküldü.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.52, "chapter": 2, "audio": ""}, "pages2": {"text": "Bir sayfada Selvi'nin el yazısı var: Abi, adımı sen yazma. Altında senin imzan.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 8.8, "chapter": 2, "audio": ""}, "altar2": {"text": "Dönmeyenler bir pazarlık teklif ediyor. Deniz hiçbir şeyi bedelsiz geri vermez.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.08, "chapter": 2, "audio": ""}, "story3": {"text": "Bu taht seni kâtip yaptı. Kral sana kalemi verdiğinde, kendi adını çoktan satmıştı.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.41, "chapter": 3, "audio": ""}, "truth3": {"text": "Kral düşerken gülüyor: Defter benden önce de vardı, benden sonra da olacak. Onu tutan el Kadı'nındır.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 10.08, "chapter": 3, "audio": ""}, "rescue3": {"text": "Kör taşçı, yazdığın her adı mezar taşına oymuştu. Şimdi senin adının üstünü çizdi.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.27, "chapter": 3, "audio": ""}, "hunt3": {"text": "Kehanetçi Ulvi düştü. Son kehaneti: Kâtip, kendi adını kendi eliyle yazacak.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 8.32, "chapter": 3, "audio": ""}, "pages3": {"text": "Bütün sayfaların altında aynı mühür var. Ne kralın, ne çancının. Kara Kadı'nın.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 8.23, "chapter": 3, "audio": ""}, "altar3": {"text": "Kralın kadehi hâlâ dolu. İçenlerin hiçbiri susuzluktan ölmedi; hepsi tahta zincirlendi.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.9, "chapter": 3, "audio": ""}, "story4": {"text": "Defter'e yazılan her ad burada zincire döküldü. Bir yerlerde Selvi'nin halkası da yanıyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.61, "chapter": 4, "audio": ""}, "truth4": {"text": "Ocak söndü. Küllerin arasında küçük bir halka var. Üzerinde tek bir ad: Selvi. Halka boş. O yanmadı.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 13.99, "chapter": 4, "audio": ""}, "rescue4": {"text": "Yusuf bin halka dövdü. Şimdi senin kılıcını dövüyor, bin halkanın bedeli olsun diye.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.85, "chapter": 4, "audio": ""}, "hunt4": {"text": "Kül Veziri düştü. Kadı'ya giden yol cübbesine dikilmiş: mürekkepten bir nehir ve sonsuz raflar.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.75, "chapter": 4, "audio": ""}, "pages4": {"text": "Yanık sayfalarda yalnız senin adın kalmış. Bahtiyar. Kâtip. Boş satır. Mürekkep taze; biri hâlâ yazıyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 13.19, "chapter": 4, "audio": ""}, "altar4": {"text": "Kanlı örs, bir demircinin vermesi gerekeni bekliyor: kanını.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 4.28, "chapter": 4, "audio": ""}, "story5": {"text": "Selvi burada. Kadı onu kâtip yapmış. Bir zamanlar senin oturduğun masada, senin kalemini tutuyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 9.67, "chapter": 5, "audio": ""}, "ch5Intro": {"text": "Mürekkep hiç kurumadı. Defter seni bekliyor, kâtip. Son satır hâlâ boş.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 8.46, "chapter": 5, "audio": ""}, "ch5Checkpoint": {"text": "Yemin taşı son kez adını hatırlıyor. Ötesi, mührün salonu.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 5.8, "chapter": 5, "audio": ""}, "ch5Boss": {"text": "Kara Kadı. Bütün hükümleri o mühürledi. Onun mührünü kır.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.98, "chapter": 5, "audio": ""}, "ch5Win": {"text": "Kadı'nın mührü kırıldı. Kalem senin elinde. Son satıra ne yazacaksın?", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.64, "chapter": 5, "audio": ""}, "ch5Death": {"text": "Defter adını yazmaya hazırlanıyor. Daha değil. Kalk.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.41, "chapter": 5, "audio": ""}, "questSeals": {"text": "Efendilerin mühürleri yerinde. Defter'in kilidi çözüldü.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 5.36, "chapter": 5, "audio": ""}, "questSelvi": {"text": "Selvi'nin kararını verdin. Kalem artık onun elinde değil.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 5.4, "chapter": 5, "audio": ""}, "selviFreed": {"text": "Selvi kalemi bırakıyor. Abi, diyor. Adımı sen yazdın, biliyorum. Yine de geldin.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 10.13, "chapter": 5, "audio": ""}, "hunt5": {"text": "Mürekkep Cellatı düştü. Kanı siyah değil; yalnızca mürekkep.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 5.84, "chapter": 5, "audio": ""}, "pages5": {"text": "Son sayfa. Selvi'nin adını yazan el titremiyor. O el senin. Korkudan yazdın. Artık biliyorsun.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 12.61, "chapter": 5, "audio": ""}, "altar5": {"text": "Boş satır. Adını şimdi yazarsan, Defter seni Kadı'dan önce tanır.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 6.0, "chapter": 5, "audio": ""}, "endingName": {"text": "Adını son satıra yazıyorsun. Defter'deki bütün adlar soluk alıp kayboluyor. Zincirler düşerken toprak seni geri çağırıyor. Bu kez korkmadan yatıyorsun. Selvi güneşe çıkıyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 17.52, "chapter": 5, "audio": ""}, "endingBurn": {"text": "Defter'i yakıyorsun. Bütün adlar alevle birlikte göğe yükseliyor. Mahkûmlar özgür, ama hiçbiri kim olduğunu hatırlamıyor. Selvi yüzüne bakıyor ve seni tanımıyor.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 15.11, "chapter": 5, "audio": ""}, "endingQuill": {"text": "Kalemi alıyorsun. Mürekkep elinin sıcaklığını tanıyor. Selvi'nin adını siliyorsun, sonra yeni bir sayfa açıyorsun. Kara Defter'in yeni Kadısı, kabrinden hiç çıkmayacak.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 15.53, "chapter": 5, "audio": ""}, "leanMercy": {"text": "Bıraktığın ölüler arkandan fısıldıyor: bu kâtip başka. Merhamet, Defter'in tanımadığı bir mürekkep.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 8.45, "chapter": 0, "audio": ""}, "leanWrath": {"text": "Hükmün keskinleşiyor, Bahtiyar. Yargıladıkça, mühür basan o ele benziyorsun.", "speaker": "Anlatıcı", "voice": "tr-TR-AhmetNeural", "style": "D", "duration": 7.36, "chapter": 0, "audio": ""}};
  var EN = {"story1": {"text": "For twenty years you wrote names in the Black Ledger, Bahtiyar. Every link of these chains began with your ink.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.77, "chapter": 1, "audio": ""}, "truth1": {"text": "With his last breath the executioner whispers: You wrote, I cut. The spade that buried you was your own pen.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.25, "chapter": 1, "audio": ""}, "rescue1": {"text": "The dervish has reached the oath stone. You wrote his name, and still he left you his flask.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.41, "chapter": 1, "audio": ""}, "hunt1": {"text": "The Shroud Weaver has fallen. None of the shrouds she wove were meant for the dead.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.13, "chapter": 1, "audio": ""}, "pages1": {"text": "The pages are in your hand. On the last line there is a name, its ink still wet: Selvi.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.42, "chapter": 1, "audio": ""}, "altar1": {"text": "The blood altar is still warm. Like everything that asks a price, it was waiting for you.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.89, "chapter": 1, "audio": ""}, "story2": {"text": "Selvi passed along this shore. The bellringer put her on a boat. And you wrote in the Ledger: debt paid.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.09, "chapter": 2, "audio": ""}, "truth2": {"text": "The bell is silent. The bellringer's last words: Your sister did not drown, scribe. I sold her to the King.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 10.33, "chapter": 2, "audio": ""}, "rescue2": {"text": "Kerem has reached the lantern. His father wept as he rang the bell. For the first time, someone on this shore prays for those who returned.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 11.39, "chapter": 2, "audio": ""}, "hunt2": {"text": "The Salt-Sworn has fallen. As the salt cracked, a key and a boat log spilled out.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.03, "chapter": 2, "audio": ""}, "pages2": {"text": "One page bears Selvi's handwriting: Brother, don't you write my name. Beneath it, your signature.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.41, "chapter": 2, "audio": ""}, "altar2": {"text": "The unreturned offer a bargain. The sea gives nothing back without a price.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.98, "chapter": 2, "audio": ""}, "story3": {"text": "This throne made you a scribe. When the king handed you the pen, he had already sold his own name.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.64, "chapter": 3, "audio": ""}, "truth3": {"text": "The king laughs as he falls: The Ledger was here before me, and it will remain after me. The hand that holds it is the Judge's.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 10.71, "chapter": 3, "audio": ""}, "rescue3": {"text": "The blind mason carved every name you wrote onto a gravestone. Now he has struck yours through.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.36, "chapter": 3, "audio": ""}, "hunt3": {"text": "Ulvi the seer has fallen. His last prophecy: the scribe will write his own name with his own hand.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.37, "chapter": 3, "audio": ""}, "pages3": {"text": "Every page carries the same seal. Not the king's, not the bellringer's. The Black Judge's.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.01, "chapter": 3, "audio": ""}, "altar3": {"text": "The king's cup is still full. None who drank from it died of thirst. All of them were chained to the throne.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.68, "chapter": 3, "audio": ""}, "story4": {"text": "Every name written in the Ledger was cast into a chain here. Somewhere, Selvi's link is burning too.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.9, "chapter": 4, "audio": ""}, "truth4": {"text": "The furnace is dead. Among the ashes lies a small link. One name upon it: Selvi. The link is empty. She did not burn.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 13.19, "chapter": 4, "audio": ""}, "rescue4": {"text": "Yusuf forged a thousand links. Now he forges your blade, to pay for every one of them.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.52, "chapter": 4, "audio": ""}, "hunt4": {"text": "The Ash Vizier has fallen. The road to the Judge is stitched into his robe: a river of ink, and endless shelves.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.18, "chapter": 4, "audio": ""}, "pages4": {"text": "Only your name survives on the burned pages. Bahtiyar. Scribe. Empty line. The ink is fresh. Someone is still writing.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 12.64, "chapter": 4, "audio": ""}, "altar4": {"text": "The bloody anvil waits for what a smith must give: his blood.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 4.68, "chapter": 4, "audio": ""}, "story5": {"text": "Selvi is here. The Judge has made her his scribe. At the desk where you once sat, she holds your pen.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 9.08, "chapter": 5, "audio": ""}, "ch5Intro": {"text": "The ink never dried. The Ledger is waiting for you, scribe. The last line is still empty.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.04, "chapter": 5, "audio": ""}, "ch5Checkpoint": {"text": "The oath stone remembers your name one last time. Beyond lies the hall of the seal.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.4, "chapter": 5, "audio": ""}, "ch5Boss": {"text": "The Black Judge. He sealed every sentence. Break his seal.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.0, "chapter": 5, "audio": ""}, "ch5Win": {"text": "The Judge's seal is broken. The pen is in your hand. What will you write on the last line?", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 7.65, "chapter": 5, "audio": ""}, "ch5Death": {"text": "The Ledger is ready to write your name. Not yet. Rise.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.09, "chapter": 5, "audio": ""}, "questSeals": {"text": "The masters' seals are in place. The Ledger's lock is broken.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.28, "chapter": 5, "audio": ""}, "questSelvi": {"text": "You have decided Selvi's fate. The pen is no longer in her hand.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 5.78, "chapter": 5, "audio": ""}, "selviFreed": {"text": "Selvi lets go of the pen. Brother, she says. You wrote my name, I know. Still, you came.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.72, "chapter": 5, "audio": ""}, "hunt5": {"text": "The Ink Headsman has fallen. His blood is not black. It is only ink.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.83, "chapter": 5, "audio": ""}, "pages5": {"text": "The last page. The hand that wrote Selvi's name does not tremble. That hand is yours. You wrote it in fear. Now you know.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 12.23, "chapter": 5, "audio": ""}, "altar5": {"text": "The empty line. Write your name now, and the Ledger will know you before the Judge does.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 6.89, "chapter": 5, "audio": ""}, "endingName": {"text": "You write your name on the last line. Every name in the Ledger draws breath, and fades. As the chains fall, the earth calls you back. This time you lie down without fear. Selvi walks into the sun.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 17.49, "chapter": 5, "audio": ""}, "endingBurn": {"text": "You burn the Ledger. Every name rises into the sky with the flames. The prisoners are free, but none of them remembers who they were. Selvi looks at your face, and does not know you.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 15.39, "chapter": 5, "audio": ""}, "endingQuill": {"text": "You take up the pen. The ink knows the warmth of your hand. You erase Selvi's name, then turn to a new page. The Black Ledger's new Judge will never leave his grave.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 13.81, "chapter": 5, "audio": ""}, "leanMercy": {"text": "The dead you spared whisper behind you: this scribe is different. Mercy is an ink the Ledger does not know.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.3, "chapter": 0, "audio": ""}, "leanWrath": {"text": "Your judgment grows sharper, Bahtiyar. The more you judge, the more you resemble the hand that stamps the seal.", "speaker": "Narrator", "voice": "en-US-SteffanNeural", "style": "D", "duration": 8.5, "chapter": 0, "audio": ""}};
  Object.keys(TR).forEach(function (k) { if (!B.Narration[k]) B.Narration[k] = TR[k]; });
  Object.keys(EN).forEach(function (k) { if (!B.NarrationEN[k]) B.NarrationEN[k] = EN[k]; });
})(window.BABA);
